def sum_to_n(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

def index_of(lst, x):
    try:
        return lst.index(x)
    except ValueError:
        return -1

def find_max(lst):
    if not lst:
        return None
    best = lst[0]
    for x in lst:
        if x > best:
            best = x
    return best

def most_frequent(words):
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return max(counts, key=counts.get)

def max_abs(lst):
    best = lst[0]
    for x in lst:
        if abs(x) > abs(best):
            best = x
    return best

def fib_upto(n):
    if n == 0:
        return [0]
    seq = [0, 1]
    while seq[-1] + seq[-2] <= n:
        seq.append(seq[-1] + seq[-2])
    return seq

def remove_dups(lst):
    seen = set()
    result = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def longest_run(lst):
    if not lst:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(lst)):
        if lst[i] == lst[i - 1]:
            cur += 1
            best = max(best, cur)
        else:
            cur = 1
    return best

def balanced(expr):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in expr:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def tax(income):
    if income <= 10000:
        return 0.0
    elif income <= 30000:
        return (income - 10000) * 0.10
    else:
        return 2000 + (income - 30000) * 0.20

